func TestIsLastInSector(t *testing.T) {
	expect := []struct {
		in    int
		shift uint16 // 12 for 4096-byte sectors, 9 for 512-byte sectors.
		want  bool
	}{
		{0, 12, false},
		{1, 12, false},
		{107, 12, false},
		{108, 12, false},
		{109, 12, false},
		{1131, 12, false},
		{1132, 12, true},
		{1133, 12, false},
		{2156, 12, true},
		{0, 9, false},
