// Top bit indicates success (0) or failure (1)
// 16 bits available for 'code' field at end

const ULONG kHresultCBit   = 0x20000000;
const ULONG kFacilityOmaha = 67;

#define MAKE_OMAHA_HRESULT(sev, code)                    \
    ((HRESULT)(((ULONG)(sev) << 31) |            \
               kHresultCBit |                            \
               (kFacilityOmaha << 16) |                  \
               ((ULONG)(code))))

